   grid%tail_statevars%rfield_0d => grid%solcon
  grid%tail_statevars%streams(1) = 0
  grid%tail_statevars%streams(2) = 2097152
  ENDIF
IF ( setinitval .EQ. 3 ) grid%solcon=initial_data_value
